  tokens: typeof tokens;
  currentApp: string; // Simplifié pour éviter l'alerte Sonar sur AppId
  isDark: boolean;
  isLoading: boolean;
  setAppIdentity: (id: string) => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

// ============================================
// HELPERS
