const parseJson = <T = unknown>(jsonStr?: string): T | undefined => {
  if (!jsonStr) return undefined;
  try {
    return JSON.parse(jsonStr) as T;
  } catch (e) {
    log.warn('JSON parsing error:', e);
    return undefined;
  }
};

/**
 * Helper : Nom d'organisation selon l'identité
 */
const getOrganizationName = (identityId: string): string => {
  switch (identityId) {
    case 'primary':
      return 'Joud Primaire';
    case 'college':
      return 'Joud Collège';
    case 'lycee':
      return 'Joud Lycée';
    case 'adult':
      return 'Joud Adulte';
    default:
      return 'Joud';
  }
};

