  });

  it('db=null → reste sur [] après effet', async () => {
    const id = nextId();
    setupHookMocks(null, id);

    const { result } = renderHook(() => useIdentityPalette());

    await act(async () => {
      await new Promise(resolve => setTimeout(resolve, 0));
    });

