    const db = makeDb();
    setupHookMocks(db, id);
    mockGetIdentityPalette().mockResolvedValue(['#111111', '#222222', '#333333']);

    const { result } = renderHook(() => useIdentityPalette());

    await act(async () => {
      await new Promise(resolve => setTimeout(resolve, 0));
    });

