      log.error('boom');
      expect(spyLog).not.toHaveBeenCalled();
      expect(spyWarn).not.toHaveBeenCalled();
    });

    it('forwards Error objects', () => {
      const err = new Error('test');
      log.error('caught', err);
      expect(spyError).toHaveBeenCalledWith('❌ ERROR:', 'caught', err);
