/**
 * ============================================
 * AI SERVICE
 * Service de communication avec l'IA (OpenAI/Mistral/Claude)
 * ============================================
 */

// ============================================
// TYPES
// ============================================

interface AIResponse {
  content: string;
  confidence?: number;
  suggestions?: string[];
}

interface AIRequest {
  message: string;
  context?: string;
  level?: number;
  provider: Provider;
  apiKey: string;
  model?: string;
}

type Provider = 'openai' | 'mistral' | 'claude';

interface ChatMessage {
  role: 'system' | 'user' | 'assistant';
  content: string;
}

interface ChatOptions {
  model?: string;
  maxTokens?: number;
  temperature?: number;
}

// ============================================
// SERVICE
// ============================================

class AIService {
  /**
   * Envoie un message simple à l'IA et récupère la réponse
   * Utilise sendChatMessage en interne
   */
  async sendMessage(request: AIRequest): Promise<AIResponse> {
    const messages: ChatMessage[] = [];

    if (request.context) {
      messages.push({ role: 'system', content: request.context });
    }

    messages.push({ role: 'user', content: request.message });

    const content = await this.sendChatMessage(
      request.provider,
      request.apiKey,
      messages,
      { model: request.model }
    );

    return { content };
  }

