// ============================================
// COMPOSANT
// ============================================

const WordGamesExerciseScreen = ({ navigation, route }: Props) => {
  // =================== PARAMS & THEME ===================
  const { familyId, levelId = '1' } = route.params || {};
  const numLevelId = Number.parseInt(levelId, 10);
  const { identity } = useTheme();

  // =================== PROGRESSION & NAVIGATION ===================
  const { trackItemCompletion, getFamilyProgress } = useProgress();
  const safeGoBack = useSafeNavigation(
    useCallback(() => navigation.goBack(), [navigation])
  );

  // =================== CHARGEMENT DONNÉES DB ===================
  // word_games n'a pas de sous-familles → subfamilyId = 0
  const familyIdNum = Number(familyId);
  const { module, family, contentItems, isLoading } = useExerciseContent<GameQuestion>(
    familyIdNum,
    0
  );

  const levelLabel = useLevelLabel(numLevelId);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState<number>(0);

  const totalQuestions = contentItems.length;
  const getFirstIncompleteIndex = useFirstIncompleteIndex(
    numLevelId,
    EXERCISE_TYPE,
    familyId,
    totalQuestions
  );

  // Initialisation de l'index de départ
  useEffect(() => {
    if (totalQuestions > 0) {
      setCurrentQuestionIndex(getFirstIncompleteIndex());
    }
  }, [totalQuestions, getFirstIncompleteIndex]);

  const currentQuestion = contentItems?.[currentQuestionIndex]?.data || null;
  const isLastQuestion = currentQuestionIndex === totalQuestions - 1;
  const realProgress = getFamilyProgress(numLevelId, EXERCISE_TYPE, familyId);

  // Détecter le type de jeu depuis la première question
  const gameType = currentQuestion?.type || 'definition';

  // =================== GAME STATE & HANDLERS ===================
  const gameStates = useGameState(gameType);
  const { getCurrentState } = gameStates;

713.text:
const handlers = useGameHandlers({
  question: currentQuestion as GameQuestion, // NOSONAR — generic inference limitation
  isLastQuestion,
  safeGoBack,
  setCurrentQuestionIndex,
  states: gameStates,
  progress: {
    trackItemCompletion,
    numLevelId,
    familyId,
    totalQuestions,
    currentQuestionIndex,
  },
});

// =================== ACTIVITÉ & AUTO-SAVE ===================
useExerciseActivity({
  levelId: numLevelId,
  familyId,
  familyName: family?.name || 'Word Games',
  moduleSlug: module?.slug || EXERCISE_TYPE,
  icon: family?.icon || 'gamepad-variant',
  currentIndex: currentQuestionIndex,
  totalItems: totalQuestions,
  enabled: !isLoading && !!family && !!currentQuestion,
});

useExerciseSaveOnUnmount();

// Suivi automatique de progression après validation
useEffect(() => {
  if (!family || currentQuestionIndex < 0) return;
  const currentState = getCurrentState();
  if (!currentState) return;

  const canSkip = currentState.attemptCount >= MAX_ATTEMPTS && !currentState.isCorrect;
  if (currentState.isValidated && (currentState.isCorrect || canSkip)) {
    trackItemCompletion(numLevelId, EXERCISE_TYPE, familyId, currentQuestionIndex, totalQuestions);
  }
}, [
  gameStates.definitionState,
  gameStates.blanksState,
  gameStates.sentenceState,
  gameStates.detectiveState,
  gameStates.replyState,
  gameStates.transformerState,
  currentQuestionIndex,
  family,
  numLevelId,
  familyId,
  totalQuestions,
  trackItemCompletion,
  getCurrentState,
]);

// =================== HANDLERS NAVIGATION ===================
// Note: Navigation gérée entièrement par ExerciseValidation dans les cards
// Plus besoin de handlers Précédent/Suivant manuels

714.text:
  // =================== RENDU ===================
  if (isLoading || !family || !currentQuestion) {
    return (
      <ExerciseLayout
        headerProps={{
          variant: 'exercise',
          onBack: () => {
            safeGoBack.navigate();
          },
          exerciseTitle: 'Chargement...',
        }}
      >
        <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
          <ActivityIndicator size="large" color={identity.palette.accent} />
        </View>
      </ExerciseLayout>
    );
  }

  return (
    <ExerciseLayout
      headerProps={{
        variant: 'exercise',
        onBack: () => {
          safeGoBack.navigate();
        },
        rightIcon: (
          <DynamicIcon
            name={module?.icon || 'gamepad-variant'}
            size={28}
            color={identity.header.accent}
            fallback="gamepad-variant"
          />
        ),
        showLevelBadge: true,
        levelTitle: levelLabel.badge,
        exerciseTitle: family.name,
      }}
      progressProps={{
        progressPercent: realProgress,
        progressText: `${realProgress}% • Question ${currentQuestionIndex + 1}/${totalQuestions}`,
      }}
    >
      <GameCardRenderer
        gameType={gameType}
        currentQuestion={currentQuestion}
        currentQuestionIndex={currentQuestionIndex}
        isLastQuestion={isLastQuestion}
        gameFamily={family}
        states={gameStates}
        handlers={handlers}
      />
    </ExerciseLayout>
  );
};

export default WordGamesExerciseScreen;

715.text:
/**
 * ============================================
 * HOOK: useGameHandlers
 * Gestionnaires d'événements pour tous les types de jeux WordGames
 * ============================================
 */

import { useCallback } from 'react';
import type { GameQuestion } from '../schema';
import type { UseGameStateReturn } from './useGameState';

// ============================================
// TYPES
// ============================================

interface SafeNavigation {
  navigate: () => void;
}

interface ProgressData {
  trackItemCompletion: (
    levelId: number,
    moduleId: string,
    familyId: string,
    itemIndex: number,
    totalItems: number
  ) => void;
  numLevelId: number;
  familyId: string;
  totalQuestions: number;
  currentQuestionIndex: number;
}

export interface UseGameHandlersParams {
  question: GameQuestion;
  isLastQuestion: boolean;
  safeGoBack: SafeNavigation;
  setCurrentQuestionIndex: React.Dispatch<React.SetStateAction<number>>;
  states: UseGameStateReturn;
  progress: ProgressData;
}

interface OptionGameHandlers {
  onAnswer: (option: string) => void;
  onValidate: () => void;
  onRetry: () => void;
  onNext: () => void;
}

interface SentenceGameHandlers {
  onOrder: (orderedWords: string[]) => void;
  onValidate: () => void;
  onRetry: () => void;
  onNext: () => void;
}

interface DetectiveGameHandlers {
  onAnswer: (wordIndex: number) => void;
  onValidate: () => void;
  onRetry: () => void;
  onNext: () => void;
}

interface TimedGameHandlers {
  onComplete: () => void;
}

export interface UseGameHandlersReturn {
  builder: OptionGameHandlers;
  definition: OptionGameHandlers;
  blanks: OptionGameHandlers;
  sentence: SentenceGameHandlers;
  detective: DetectiveGameHandlers;
  speed: TimedGameHandlers;
  audio_match: TimedGameHandlers;
  reply: OptionGameHandlers;
  transformer: OptionGameHandlers;
}

// ============================================
// TYPES INTERNES
// ============================================

716.text:
type OptionState = {
  selectedOption: string | null;
  isValidated: boolean;
  isCorrect: boolean;
  attemptCount: number;
};

// ============================================
// CONSTANTS
// ============================================

const MAX_ATTEMPTS = 2;
const MODULE_ID = 'word_games';
const identity = (s: string) => s;
const lowerTrim = (s: string) => s.toLowerCase().trim();

// ============================================
// HOOK
// ============================================

export const useGameHandlers = ({
  question: currentQuestion,
  isLastQuestion,
  safeGoBack,
  setCurrentQuestionIndex,
  states,
  progress,
}: UseGameHandlersParams): UseGameHandlersReturn => {
  const {
    builderState, setBuilderState,
    definitionState, setDefinitionState,
    blanksState, setBlanksState,
    sentenceState, setSentenceState,
    detectiveState, setDetectiveState,
    replyState, setReplyState,
    transformerState, setTransformerState,
    resetAllStates,
  } = states;

  const { trackItemCompletion, numLevelId, familyId, totalQuestions, currentQuestionIndex } = progress;

  // =========================================================
  // NAVIGATION CENTRALISÉE
  // =========================================================

  const handleNavigationNext = useCallback(() => {
    if (isLastQuestion) {
      safeGoBack.navigate();
    } else {
      setCurrentQuestionIndex(prev => prev + 1);
      resetAllStates();
    }
  }, [isLastQuestion, safeGoBack, setCurrentQuestionIndex, resetAllStates]);

  // =========================================================
  // FACTORY QCM (definition, blanks, reply, transformer, builder)
  // Tous ces types partagent le même pattern : selectedOption + compare + track
  // =========================================================

717.text:
const makeOptionHandlers = (
  state: Pick<OptionState, 'selectedOption' | 'attemptCount'>,
  setState: React.Dispatch<React.SetStateAction<OptionState>>,
  questionType: string,
  normalize: (s: string) => string = identity,
): OptionGameHandlers => ({
  onAnswer: (option: string) => setState(prev => ({ ...prev, selectedOption: option })),
  onValidate: () => {
    if (!state.selectedOption || currentQuestion.type !== questionType) return;
    const correct = normalize(state.selectedOption) === normalize((currentQuestion as { correctAnswer: string }).correctAnswer);
    setState(prev => ({ ...prev, isValidated: true, isCorrect: correct, attemptCount: prev.attemptCount + 1 }));
    if (correct || state.attemptCount + 1 >= MAX_ATTEMPTS) {
      trackItemCompletion(numLevelId, MODULE_ID, familyId, currentQuestionIndex, totalQuestions);
    }
  },
  onRetry: () => setState(prev => ({ ...prev, selectedOption: null, isValidated: false, isCorrect: false })),
  onNext: handleNavigationNext,
});

// =========================================================
// HANDLERS: SENTENCE BUILDER (ordre de mots — logique spécifique)
// =========================================================

718.text:
const sentence: SentenceGameHandlers = {
  onOrder: (orderedWords: string[]) => setSentenceState(prev => ({ ...prev, selectedOrder: orderedWords })),
  onValidate: () => {
    if (sentenceState.selectedOrder.length === 0 || currentQuestion.type !== 'sentence') return;
    const correct = JSON.stringify(sentenceState.selectedOrder) === JSON.stringify(currentQuestion.correctOrder);
    setSentenceState(prev => ({ ...prev, isValidated: true, isCorrect: correct, attemptCount: prev.attemptCount + 1 }));
    if (correct || sentenceState.attemptCount + 1 >= MAX_ATTEMPTS) {
      trackItemCompletion(numLevelId, MODULE_ID, familyId, currentQuestionIndex, totalQuestions);
    }
  },
  onRetry: () => setSentenceState(prev => ({ ...prev, selectedOrder: [], isValidated: false, isCorrect: false })),
  onNext: handleNavigationNext,
};

// =========================================================
// HANDLERS: DETECTIVE (wordIndex — logique spécifique)
// =========================================================

const detective: DetectiveGameHandlers = {
  onAnswer: (wordIndex: number) => setDetectiveState(prev => ({ ...prev, selectedWord: wordIndex })),
  onValidate: () => {
    if (detectiveState.selectedWord === null || detectiveState.selectedWord === undefined || currentQuestion.type !== 'detective') return;
    const correct = detectiveState.selectedWord === currentQuestion.errorWordIndex;
    setDetectiveState(prev => ({ ...prev, isValidated: true, isCorrect: correct, attemptCount: prev.attemptCount + 1 }));
    if (correct || detectiveState.attemptCount + 1 >= MAX_ATTEMPTS) {
      trackItemCompletion(numLevelId, MODULE_ID, familyId, currentQuestionIndex, totalQuestions);
    }
  },
  onRetry: () => setDetectiveState(prev => ({ ...prev, selectedWord: null, isValidated: false, isCorrect: false })),
  onNext: handleNavigationNext,
};

719.text:
  // =========================================================
  // HANDLERS: SPEED MATCH / AUDIO MATCH (timer interne)
  // =========================================================

  const handleTimedComplete = () => {
    trackItemCompletion(numLevelId, MODULE_ID, familyId, currentQuestionIndex, totalQuestions);
    handleNavigationNext();
  };

  // =========================================================
  // RETURN
  // =========================================================

  return {
    builder:     makeOptionHandlers(builderState, setBuilderState, 'definition', lowerTrim),
    definition:  makeOptionHandlers(definitionState, setDefinitionState, 'definition'),
    blanks:      makeOptionHandlers(blanksState, setBlanksState, 'blanks'),
    reply:       makeOptionHandlers(replyState, setReplyState, 'reply'),
    transformer: makeOptionHandlers(transformerState, setTransformerState, 'transformer'),
    sentence,
    detective,
    speed:       { onComplete: handleTimedComplete },
    audio_match: { onComplete: handleTimedComplete },
  };
};

720.text:
/**
 * ============================================
 * HOOK: useGameState
 * Gestion des états pour tous les types de jeux WordGames
 * ============================================
 */

import { useState, useCallback, useMemo, Dispatch, SetStateAction } from 'react';
import type { GameType } from '../schema';

// ============================================
// TYPES
// ============================================

/**
 * État pour jeux avec sélection d'option (Definition, Blanks, Reply, Transformer, Builder)
 */
export interface OptionGameState {
  selectedOption: string | null;
  isValidated: boolean;
  isCorrect: boolean;
  attemptCount: number;
}

/**
 * État pour jeu de construction de phrase (Sentence Builder)
 */
export interface SentenceGameState {
  selectedOrder: string[];
  isValidated: boolean;
  isCorrect: boolean;
  attemptCount: number;
}

/**
 * État pour jeu Detective (sélection d'un mot par index)
 */
export interface DetectiveGameState {
  selectedWord: number | null;
  isValidated: boolean;
  isCorrect: boolean;
  attemptCount: number;
}

/**
 * Union type pour tous les états possibles
 */
export type GameState = OptionGameState | SentenceGameState | DetectiveGameState;

/**
 * Mapping des types de jeux aux états
 * Note: 'speed' et 'audio_match' n'ont pas d'état ici car ils gèrent leur état en interne
 */
export interface AllGameStates {
  builder: OptionGameState;
  definition: OptionGameState;
  blanks: OptionGameState;
  sentence: SentenceGameState;
  detective: DetectiveGameState;
  reply: OptionGameState;
  transformer: OptionGameState;
}

721.text:
/**
 * Valeur de retour du hook
 */
export interface UseGameStateReturn {
  // États individuels
  builderState: OptionGameState;
  setBuilderState: Dispatch<SetStateAction<OptionGameState>>;
  definitionState: OptionGameState;
  setDefinitionState: Dispatch<SetStateAction<OptionGameState>>;
  blanksState: OptionGameState;
  setBlanksState: Dispatch<SetStateAction<OptionGameState>>;
  sentenceState: SentenceGameState;
  setSentenceState: Dispatch<SetStateAction<SentenceGameState>>;
  detectiveState: DetectiveGameState;
  setDetectiveState: Dispatch<SetStateAction<DetectiveGameState>>;
  replyState: OptionGameState;
  setReplyState: Dispatch<SetStateAction<OptionGameState>>;
  transformerState: OptionGameState;
  setTransformerState: Dispatch<SetStateAction<OptionGameState>>;

  // Utilitaires
  resetAllStates: () => void;
  getCurrentState: () => GameState | null;
}

// ============================================
// CONSTANTS
// ============================================

const INITIAL_OPTION_STATE: OptionGameState = {
  selectedOption: null,
  isValidated: false,
  isCorrect: false,
  attemptCount: 0,
};

const INITIAL_SENTENCE_STATE: SentenceGameState = {
  selectedOrder: [],
  isValidated: false,
  isCorrect: false,
  attemptCount: 0,
};

const INITIAL_DETECTIVE_STATE: DetectiveGameState = {
  selectedWord: null,
  isValidated: false,
  isCorrect: false,
  attemptCount: 0,
};

