  variantColor: 'primary' | 'accent'; // Clé stricte du palette (primary ou accent)
  onPress?: () => void;
  children?: React.ReactNode;
  showArrow?: boolean;
}

const DashboardCard: React.FC<DashboardCardProps> = ({
  icon,
  title,
  subtitle,
  buttonText,
