export const useAdvancedErrorAnalysis = () => {
  const { db } = useUser();
  const [analysis, setAnalysis] = useState<GlobalAnalysis | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const performAnalysis = async () => {
      if (!db || typeof db === 'number') {
        setIsLoading(false);
        return;
      }

      try {
        setIsLoading(true);
        const now = Date.now();
        const periodStart = now - (ANALYSIS_PERIOD_DAYS * 24 * 60 * 60 * 1000);
        const trendStart = now - (TREND_COMPARISON_DAYS * 24 * 60 * 60 * 1000);

        // =================== ANALYSE PAR MODULE ===================

        const moduleStats = await db.getAllAsync<{
          module_slug: string;
          error_count: number;
          distinct_families: number;
          last_error: number;
        }>(
          `SELECT
            module_slug,
            COUNT(*) as error_count,
            COUNT(DISTINCT family_id) as distinct_families,
            MAX(timestamp) as last_error
           FROM exercise_errors
           WHERE timestamp > ?
           GROUP BY module_slug
           ORDER BY error_count DESC`,
          [periodStart]
        );

        const moduleAnalyses: ModuleAnalysis[] = [];

        // Pré-charger les noms de modules depuis module_labels ou modules
        const moduleNamesMap = new Map<string, string>();
        const allModules = await db.getAllAsync<{ slug: string; name: string }>(
          `SELECT slug, name FROM modules`
        );
        for (const m of allModules) {
          moduleNamesMap.set(m.slug, m.name);
        }

