/**
 * SkeletonLoader - Composant de chargement moderne (2026 standard)
 * Supporte les modes playful et clean avec animations fluides
 */

import React, { useEffect } from 'react';
import { View, StyleSheet, ViewStyle } from 'react-native';
import Animated, {
  useSharedValue,
  useAnimatedStyle,
  withRepeat,
  withTiming,
  Easing,
} from 'react-native-reanimated';
import { useTheme } from '@/themes/ThemeContext';
import { tokens } from '@/themes/tokens';

// ============================================
// TYPES
// ============================================

interface SkeletonLoaderProps {
  variant?: 'card' | 'grid-item' | 'recent-activity';
  style?: ViewStyle;
}

interface SkeletonItemProps {
  width: number | string;
  height: number | string;
  borderRadius?: number;
  style?: ViewStyle;
}

// ============================================
// SKELETON ITEM (Élément atomique)
// ============================================

const SkeletonItem: React.FC<SkeletonItemProps> = ({
  width,
  height,
  borderRadius = 8,
  style
}) => {
  const { isDark } = useTheme();
  const opacity = useSharedValue(0.3);

  useEffect(() => {
    opacity.value = withRepeat(
      withTiming(1, {
        duration: 1200,
        easing: Easing.inOut(Easing.ease),
      }),
      -1, // Infini
      true // Reverse
    );
  }, [opacity]);

  const animatedStyle = useAnimatedStyle(() => ({
    opacity: opacity.value,
  }));

  const baseColor = isDark ? '#374151' : '#E5E7EB';

  return (
    <View
      style={[
        {
          width: width as number,
          height: height as number,
          borderRadius,
          backgroundColor: baseColor,
          overflow: 'hidden',
        },
        style,
      ]}
    >
      <Animated.View
        style={[
          {
            width: '100%',
            height: '100%',
            backgroundColor: baseColor,
          },
          animatedStyle,
        ]}
      />
    </View>
  );
};

