          {data.phrase_fr || data.translation}
        </Text>
      </View>

      {/* 2. BLOC ASTUCE (optionnel) */}
      {data.tip && (
        <View style={styles.tipBlock}>
          <Text style={styles.tipLabel}>💡 Tip</Text>
          <Text style={styles.tipText}>{data.tip}</Text>
        </View>
      )}

