  const minHeight = HEADER_HEIGHTS[identityId] || HEADER_HEIGHTS.college;

  return StyleSheet.create({
    headerContainer: {
      paddingTop: spacing.top,
      paddingBottom: spacing.bottom,
      paddingHorizontal: tokens.spacing.md,
      minHeight,
      position: 'relative',
      overflow: 'hidden',
