      }),
      Animated.spring(scaleAnim, {
        toValue: 1,
        tension: 100,
        friction: 7,
        useNativeDriver: true,
      }),
    ]).start();
  }, [feedback, slideAnim, fadeAnim, scaleAnim]);

  if (!feedback) return null;

