/**
 * ExerciseValidation - Composant principal
 */
const ExerciseValidation: React.FC<ExerciseValidationProps> = ({
  state = 'initial',
  onValidate,
  onNext,
  onRetry,
  onSkip,
  disabled = false,
  showFeedback = true,
  feedbackMessage = null,
  isLastQuestion = false,
  attemptCount = 0,
  maxAttempts = 2,
  correctAnswer = null,
}) => {
  const { identity } = useTheme();
